-- تصحيح تخريج وألفاظ الطبقة الحديثية في lesson_sections — الدفعة الخامسة (الدروس 101–150)
-- المصدر السابع والعشرون `lessons` ضمن التدقيق الدوري الشامل (سجل ج-٢١٤).
-- المنهج: قوبل كل اقتباس بين «» أو "" بنص الطبعات الست كاملةً (البخاري 7589، مسلم 7563،
-- أبو داود 5274، الترمذي 3998، النسائي 5765، ابن ماجه 4343 = 34532 حديثًا) المنزَّلة من
-- نفس CDN الذي تعتمده المنصة (fawazahmed0/hadith-api عبر jsDelivr، راجع
-- src/lib/hadith-cdn-service.ts). عُيِّر المُطبِّع قبل أي حكم على «اجتنبوا السبع الموبقات»
-- ⇒ bukhari h2766 و muslim a89 بتغطية 1.00. البخاري وغيره يُطابَق على hadithnumber،
-- ومسلم على arabicnumber (ترقيم فؤاد عبد الباقي) مع أخذ الجزء الصحيح من الرقم لتغطية الطرق
-- ذات اللواحق العشرية.
-- القاعدة المتَّبعة: يُصحَّح التخريج لا المتن متى كان المتن منقولًا حرفيًّا من مصدر صحيح؛
-- ولا يُمسّ المتن إلا حين لا يوجد لفظه في أي من الستة (متن مركَّب) فيُردّ حرفيًّا إلى لفظ
-- المصدر المسمَّى نفسه. لم يُولَّد حرف ديني واحد؛ كل بديل منقول حرفيًّا من الطبعة.
-- الملف idempotent: كل جملة replace() مشروطة بوجود النص القديم.

BEGIN;

-- (١) rn2 — إسناد وتخريج معًا: «ليس منا من دعا إلى عصبية…» نُسب لأبي هريرة وعُزي لمسلم؛ ولا وجود له في مسلم أصلًا، ولفظه حرفيًّا (تغطية 1.00) عند أبي داود 5121 من حديث جُبَير بن مُطعِم. فصُحِّح الصحابي والمخرِّج معًا.
UPDATE lesson_sections SET content = replace(content, 'وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال:', 'وعن جبير بن مطعم رضي الله عنه أن رسول الله صلى الله عليه وسلم قال:'), updated_at = now()
  WHERE id = '7e927f56-f547-492c-9a3b-edc18e2e184d' AND content LIKE '%وعن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال:%';

--      تتمة (١): تصحيح العزو من «رواه مسلم» إلى «رواه أبو داود (5121)».
UPDATE lesson_sections SET content = replace(content, '، رواه مسلم.', '، رواه أبو داود (5121).'), updated_at = now()
  WHERE id = '7e927f56-f547-492c-9a3b-edc18e2e184d' AND content LIKE '%، رواه مسلم.%';

-- (٢) rn22 — لفظ الترمذي 3513 في الطبعة: «اللهم إنك عفو كريم تحب العفو فاعف عني» بزيادة «كريم»، واللفظ المخزَّن بلا «كريم» هو لفظ ابن ماجه 3850. لم يُمسّ المتن (نسخ الترمذي مختلفة في «كريم» وليس لي أن أرجّح)، وإنما أُضيف رقم ابن ماجه وبُيِّن لفظ الترمذي.
UPDATE lesson_sections SET content = replace(content, '(رواه الترمذي 3513 وأحمد وابن ماجه، وقال الترمذي: حديث حسن صحيح', '(رواه الترمذي 3513 وابن ماجه 3850 وأحمد، ولفظه عند الترمذي: «اللهم إنك عفو كريم تحب العفو فاعف عني»، وقال الترمذي: حديث حسن صحيح'), updated_at = now()
  WHERE id = '0523e291-d4a3-42cd-9ab4-df701116ac78' AND content LIKE '%(رواه الترمذي 3513 وأحمد وابن ماجه، وقال الترمذي: حديث حسن صحيح%';

-- (٣) rn29 — «متفق عليه» غير صحيحة: مسلم 779 متنُه في البيت لا في الذاكر («مثل البيت الذي يُذكر الله فيه…»)، والحديث بلفظ الذاكر عند البخاري 6407 وحده. وزيادة «ربه» الثانية ليست في لفظ البخاري 6407، فرُدّت إلى لفظه.
UPDATE lesson_sections SET content = replace(content, '«مثل الذي يذكر ربه والذي لا يذكر ربه، مثل الحي والميت» (متفق عليه، رواه البخاري 6407 ومسلم 779).', '«مثل الذي يذكر ربه والذي لا يذكر، مثل الحي والميت» (رواه البخاري 6407، وروى مسلم 779 نحوه بلفظ: «مثل البيت الذي يُذكر الله فيه والبيت الذي لا يُذكر الله فيه مثل الحي والميت»).'), updated_at = now()
  WHERE id = '0561258a-66ff-438f-971c-d21c5d1cd7a7' AND content LIKE '%«مثل الذي يذكر ربه والذي لا يذكر ربه، مثل الحي والميت» (متفق عليه، رواه البخاري 6407 ومسلم 779).%';

-- (٤) rn31 — ابن ماجه 2275 (عن ابن مسعود، وهو الصحابي المصرَّح به في القسم) لفظه «الربا ثلاثة وسبعون بابًا» فقط؛ وجملة «أيسرها…» إنما هي في ابن ماجه 2274 عن أبي هريرة بلفظ «الربا سبعون حوبًا أيسرها أن ينكح الرجل أمه». فالمتن المخزَّن مركَّب من طريقين، ورُدّ كلٌّ إلى موضعه بلفظه ورقمه.
UPDATE lesson_sections SET content = replace(content, '«الرِّبَا ثَلَاثَةٌ وَسَبْعُونَ بَابًا، أَيْسَرُهَا مِثْلُ أَنْ يَنْكِحَ الرَّجُلُ أُمَّهُ»، رواه ابن ماجه وصححه الألباني.', '«الرِّبَا ثَلَاثَةٌ وَسَبْعُونَ بَابًا»، رواه ابن ماجه (2275) وصححه الألباني. وعن أبي هريرة رضي الله عنه عند ابن ماجه (2274): «الرِّبَا سَبْعُونَ حُوبًا، أَيْسَرُهَا أَنْ يَنْكِحَ الرَّجُلُ أُمَّهُ».'), updated_at = now()
  WHERE id = 'a1f3f9ba-8581-4bfa-b6af-397d27fc9950' AND content LIKE '%«الرِّبَا ثَلَاثَةٌ وَسَبْعُونَ بَابًا، أَيْسَرُهَا مِثْلُ أَنْ يَنْكِحَ الرَّجُلُ أُمَّهُ»، رواه ابن ماجه وصححه الألباني.%';

-- (٥) rn37 — زيادة «فادفعها إليه» ليست في لفظ الشيخين (البخاري 2372 ومسلم 1722): «فإن جاء صاحبها وإلا فشأنك بها»؛ وأُضيف الرقمان. وصُحِّح «إذ سأل النبي ﷺ» إلى «إذ سُئل» لأن السائل رجل والراوي زيد بن خالد (تصحيح تحريري لا نصّي).
UPDATE lesson_sections SET content = replace(content, 'إذ سأل النبي ﷺ عن اللقطة فقال: «اعرف عفاصها ووكاءها، ثم عرِّفها سنة، فإن جاء صاحبها فادفعها إليه، وإلا فشأنك بها».', 'إذ سُئل النبي ﷺ عن اللقطة فقال: «اعرف عفاصها ووكاءها، ثم عرِّفها سنة، فإن جاء صاحبها وإلا فشأنك بها» (رواه البخاري 2372 ومسلم 1722).'), updated_at = now()
  WHERE id = 'dd80d270-ab13-404d-af5d-fd18ecd39877' AND content LIKE '%إذ سأل النبي ﷺ عن اللقطة فقال: «اعرف عفاصها ووكاءها، ثم عرِّفها سنة، فإن جاء صاحبها فادفعها إليه، وإلا فشأنك بها».%';

-- (٦) rn43 — المتن مركَّب لا يوافق أيًّا من المصدرين: البخاري 4552 لفظه «لذهب دماء قوم وأموالهم» ثم «اليمين على المدعى عليه»، ومسلم 1711 «لادعى ناس دماء رجال وأموالهم ولكن اليمين على المدعى عليه»؛ و«البينة على المدعي واليمين على من أنكر» ليست في الستة، وأقرب ما فيها الترمذي 1341 «واليمين على المدعى عليه» وقال: في إسناده مقال. فرُدّ المتن حرفيًّا إلى لفظ مسلم 1711 وبُيِّن الباقي.
UPDATE lesson_sections SET content = replace(content, '«لو يُعطى الناس بدعواهم لادَّعى رجال أموال قوم ودماءهم، ولكن البينة على المدَّعي واليمين على من أنكر» (متفق عليه، رواه البخاري 4552 ومسلم 1711)', '«لو يُعطى الناس بدعواهم لادَّعى ناس دماء رجال وأموالهم، ولكن اليمين على المدَّعى عليه» (رواه مسلم 1711 واللفظ له، وأصله في صحيح البخاري 4552 بلفظ: «لو يُعطى الناس بدعواهم لذهب دماء قوم وأموالهم» وفيه: «اليمين على المدَّعى عليه»؛ ولفظ: «البينة على المدَّعي واليمين على المدَّعى عليه» عند الترمذي 1341 وقال: هذا حديث في إسناده مقال)'), updated_at = now()
  WHERE id = '96bbe05e-a164-4990-974f-2e6d263f60d8' AND content LIKE '%«لو يُعطى الناس بدعواهم لادَّعى رجال أموال قوم ودماءهم، ولكن البينة على المدَّعي واليمين على من أنكر» (متفق عليه، رواه البخاري 4552 ومسلم 1711)%';

-- (٧) rn46 — متن هجين بين طريقي بعث معاذ: «إنك تأتي قومًا من أهل الكتاب» صدر مسلم 19، و«فليكن أول ما تدعوهم إليه» إنما يتلوها «عبادة الله» (البخاري 1458 ومسلم 19.03) أو «أن يوحدوا الله» (البخاري 7372) لا «شهادة أن لا إله إلا الله». فرُدّ حرفيًّا إلى لفظ مسلم 19 وأُضيف رقما الصحيحين (البخاري 1395).
UPDATE lesson_sections SET content = replace(content, '"إنك تأتي قومًا من أهل الكتاب، فليكن أول ما تدعوهم إليه شهادة أن لا إله إلا الله، فإن هم أطاعوا لذلك فأعلمهم أن الله قد افترض عليهم خمس صلوات في كل يوم وليلة..."، متفق عليه.', '"إنك تأتي قومًا من أهل الكتاب، فادعهم إلى شهادة أن لا إله إلا الله وأني رسول الله، فإن هم أطاعوا لذلك فأعلمهم أن الله افترض عليهم خمس صلوات في كل يوم وليلة..."، متفق عليه، رواه البخاري (1395) ومسلم (19) واللفظ له.'), updated_at = now()
  WHERE id = '1916d3e0-4c99-4451-a797-d2709b7fdc50' AND content LIKE '%"إنك تأتي قومًا من أهل الكتاب، فليكن أول ما تدعوهم إليه شهادة أن لا إله إلا الله، فإن هم أطاعوا لذلك فأعلمهم أن الله قد افترض عليهم خمس صلوات في كل يوم وليلة..."، متفق عليه.%';

-- (٨) rn52 — «فأداها كما سمعها» ليست في أيٍّ من الستة؛ ولفظ الترمذي 2658 (وهو حديث ابن مسعود المصرَّح به): «فوعاها وحفظها وبلغها». فرُدّ إلى لفظ المصدر المسمَّى نفسه وأُضيف رقمه.
UPDATE lesson_sections SET content = replace(content, 'فَوَعَاهَا فَأَدَّاهَا كَمَا سَمِعَهَا، فَرُبَّ حَامِلِ فِقْهٍ إِلَى مَنْ هُوَ أَفْقَهُ مِنْهُ» رواه الترمذي وقال: حسن صحيح', 'فَوَعَاهَا وَحَفِظَهَا وَبَلَّغَهَا، فَرُبَّ حَامِلِ فِقْهٍ إِلَى مَنْ هُوَ أَفْقَهُ مِنْهُ» رواه الترمذي (2658)، وقال في حديث ابن مسعود هذا: حسن صحيح'), updated_at = now()
  WHERE id = '14d78da5-afdf-4377-89d5-c7f7aaebb39a' AND content LIKE '%فَوَعَاهَا فَأَدَّاهَا كَمَا سَمِعَهَا، فَرُبَّ حَامِلِ فِقْهٍ إِلَى مَنْ هُوَ أَفْقَهُ مِنْهُ» رواه الترمذي وقال: حسن صحيح%';

COMMIT;
